/* From Uiverse.io by Yaya12085 - Tags: button */
.__UIV_SCOPE__ .btn {
  position: relative;
  outline: 0;
  border: 1px solid transparent;
  background-color: #488aec;
  color: #ffffff;
  font-size: 0.75rem;
  line-height: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
  overflow: hidden;
  box-shadow: 0 4px 6px -1px #488aec31, 0 2px 4px -1px #488aec17;
}

.__UIV_SCOPE__ .btn span {
  height: 100%;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  transition: all .4s ease;
}

.__UIV_SCOPE__ button svg {
  width: 1.25rem;
  height: 1.25rem;
}

.__UIV_SCOPE__ .btn span:nth-child(2),.__UIV_SCOPE__ .btn span:nth-child(3) {
  position: absolute;
  top: 40px;
  color: #fff;
}

.__UIV_SCOPE__ .btn span:nth-child(2) {
  background-color: #488aec;
}

.__UIV_SCOPE__ .btn span:nth-child(3) {
  background-color: #488aec;
}

.__UIV_SCOPE__ .btn:hover {
  box-shadow: 0 10px 15px -3px #488aec4f, 0 4px 6px -2px #488aec17;
}

.__UIV_SCOPE__ .btn:hover span:nth-child(2), .__UIV_SCOPE__ .btn:focus span:nth-child(3) {
  top: 0;
}

.__UIV_SCOPE__ .btn:focus {
  box-shadow: none;
}
